@import "tailwindcss";

@theme inline {
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);

  /* Brand palette — Majoo-style bright green (primary ~#00A651). */
  --color-brand-50: #e6f9f0;
  --color-brand-100: #c3f0dc;
  --color-brand-200: #8fe0be;
  --color-brand-300: #57ce9c;
  --color-brand-400: #22b87a;
  --color-brand-500: #00a651;
  --color-brand-600: #00944a;
  --color-brand-700: #007a3d;
  --color-brand-800: #005c2e;
  --color-brand-900: #003d1f;
}

/* Situs ini belum didesain untuk dark mode (semua komponen pakai warna
   terang secara eksplisit) — sengaja TIDAK ada @media (prefers-color-scheme:
   dark) di sini. Versi sebelumnya punya aturan itu (sisa template default
   Next.js) yang bikin body.color jadi hampir putih (#ededed) saat OS
   pengunjung mode gelap, sementara kotak form/input tetap putih — teks yang
   diketik di form (mis. login) jadi nyaris tidak terlihat. Kalau dark mode
   beneran mau didukung nanti, harus didesain menyeluruh, bukan cuma body.
*/
body {
  background: #ffffff;
  color: #171717;
  font-family: Arial, Helvetica, sans-serif;
}

