5	
6	const CHART_BARS = [40, 65, 50, 80, 60, 95, 70];
7	const CART_ITEMS = [
8	  { name: "Kopi Susu", qty: 2, price: "Rp36.000" },
9	  { name: "Roti Bakar", qty: 1, price: "Rp18.500" },
10	];
11	
12	const SLIDE_LABELS = ["Dashboard", "Kasir", "Laporan"];
13	
14	function DashboardSlide() {
15	  return (
16	    <>
17	      <div className="mt-5 grid grid-cols-2 gap-3">
18	        <div className="rounded-xl bg-zinc-50 p-3">
