96	// Kartu preview di hero — dulu cuma nampilin Dashboard statis, sekarang jadi
97	// carousel 3 layar (Dashboard/Kasir/Laporan) yang bisa di-geser di HP dan
98	// otomatis gonta-ganti, supaya pengunjung langsung lihat lebih dari satu
99	// bagian aplikasi tanpa harus daftar dulu.
100	export default function HeroPreview() {
101	  const [active, setActive] = useState(0);
102	  const touchStartX = useRef<number | null>(null);
103	
104	  useEffect(() => {
105	    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
106	    if (reduceMotion) return;
107	    const timer = setInterval(() => {
108	      setActive((a) => (a + 1) % SLIDE_LABELS.length);
109	    }, 3200);
110	    return () => clearInterval(timer);
111	  }, []);
112	
113	  function onTouchStart(e: React.TouchEvent) {
114	    touchStartX.current = e.touches[0].clientX;
115	  }
116	
117	  function onTouchEnd(e: React.TouchEvent) {
118	    if (touchStartX.current === null) return;
119	    const delta = e.changedTouches[0].clientX - touchStartX.current;
120	    if (Math.abs(delta) > 40) {
121	      setActive((a) => {
122	        const dir = delta < 0 ? 1 : -1;
123	        return (a + dir + SLIDE_LABELS.length) % SLIDE_LABELS.length;
124	      });
125	    }
126	    touchStartX.current = null;
127	  }
128	
129	  return (
130	    <div className="relative mx-auto w-full max-w-sm">
131	      <div aria-hidden className="absolute -top-5 -right-5 h-20 w-20 rounded-2xl bg-amber-200/60" />
132	      <div aria-hidden className="absolute -bottom-6 -left-6 h-24 w-24 rounded-full bg-brand-200/60" />
133	
134	      <div className="relative rounded-3xl border border-zinc-200 bg-white p-6 shadow-2xl shadow-zinc-300/40">
135	        <div className="flex items-center gap-1.5">
136	          <span className="h-2.5 w-2.5 rounded-full bg-red-300" />
137	          <span className="h-2.5 w-2.5 rounded-full bg-amber-300" />
138	          <span className="h-2.5 w-2.5 rounded-full bg-emerald-300" />
139	        </div>
140	
141	        <div className="mt-4 flex items-center gap-3">
142	          <Logo className="h-10 w-10" />
143	          <div className="min-w-0">
144	            <p className="truncate text-sm font-bold text-zinc-900">Toko Kamu</p>
145	            <p className="text-xs text-zinc-400">{SLIDE_LABELS[active]}</p>
146	          </div>
147	          <span className="ml-auto shrink-0 rounded-full bg-brand-50 px-2 py-0.5 text-[10px] font-medium text-brand-700">
148	            ● Shift aktif
149	          </span>
150	        </div>
