  price: number;
  qty: number;
  maxStock: number;
  disc: number;
  discType: DiscountType;
  note: string | null;
};

type Tender = {
  id: string;
  method: string;
  amount: number;
  received: string;
};

type SelfOrder = {
  id: string;
