            return (
              <button
                key={prod.name}
                type="button"
                onClick={() => setSelected(i)}
                className={`w-full border-t border-zinc-50 px-4 py-2.5 text-left transition-colors ${
                  selected === i ? "bg-brand-50" : "hover:bg-zinc-50"
                }`}
