                    {prod.jual.toLocaleString("id-ID")}
                  </span>
                  <span className="text-xs font-bold text-brand-600">{m}%</span>
                  <span
                    className={`h-1.5 rounded-full ${
                      parseFloat(m) >= 60
                        ? "bg-brand-500"
                        : parseFloat(m) >= 40
                        ? "bg-amber-400"
                        : "bg-red-400"
